package com.sunwayworld.framework.converter.number;
import com.sunwayworld.framework.converter.*;import com.sunwayworld.framework.converter.exception.ConverterNotFoundException;import java.math.*;
public enum NumberToNumberConverterFactory implements ConverterFactory<Number,Number>{INSTANCE; public <T extends Number> Converter<Number,T> getConverter(Class<T> targetType){return new NumberToNumberConverter<T>(targetType);} private class NumberToNumberConverter<T extends Number> implements Converter<Number,T>{private final Class<T> numberType; public NumberToNumberConverter(Class<T> t){numberType=t;} public Class<Number> getSourceType(){return Number.class;} public Class<T> getTargetType(){return numberType;} @SuppressWarnings("unchecked") public T convert(Number source){if(source==null)return null;Class<T>t=numberType;if(t==Byte.class||t==Byte.TYPE)return(T)Byte.valueOf(source.byteValue());if(t==Short.class||t==Short.TYPE)return(T)Short.valueOf(source.shortValue());if(t==Integer.class||t==Integer.TYPE)return(T)Integer.valueOf(source.intValue());if(t==Long.class||t==Long.TYPE)return(T)Long.valueOf(source.longValue());if(t==Float.class||t==Float.TYPE)return(T)Float.valueOf(source.floatValue());if(t==Double.class||t==Double.TYPE)return(T)Double.valueOf(source.doubleValue());if(t==BigInteger.class)return(T)BigInteger.valueOf(source.longValue());if(t==BigDecimal.class)return(T)BigDecimal.valueOf(source.doubleValue());throw new ConverterNotFoundException(Number.class,t);}}}
